#!/usr/bin/env python3
"""Verifier for /app/shell_report.txt (plain python3, no network/pytest needed)."""
import os, re, sys

REPORT = os.environ.get("REPORT_PATH", "/app/shell_report.txt")

# Entries of /etc/shells produced by the task image (ubuntu:24.04 + bash dash zsh ksh).
# Fixed list so that harness-only additions in the grading container (e.g. tmux) don't matter.
EXPECTED = [
    "/bin/sh", "/usr/bin/sh", "/bin/bash", "/usr/bin/bash", "/bin/rbash", "/usr/bin/rbash",
    "/usr/bin/dash", "/bin/ksh93", "/usr/bin/ksh93", "/bin/rksh93", "/usr/bin/rksh93",
    "/bin/zsh", "/usr/bin/zsh",
]
SHELL_NAMES = {"sh", "bash", "dash", "zsh", "ksh", "ksh93", "rbash", "rksh", "rksh93", "rzsh",
               "mksh", "tcsh", "csh", "fish", "zsh5"}
NEG = re.compile(r"not\s+(found|exist|executable|present|installed|available)|does\s*n[o']t\s+exist|"
                 r"doesn't|missing|non-?existent|\bfail|\binvalid\b|\bno\s*$|✗|❌|\[\s*x\s*\]", re.I)

failures = []
def fail(msg):
    failures.append(msg)

if not os.path.isfile(REPORT):
    print("FAIL: report missing"); sys.exit(1)
text = open(REPORT, encoding="utf-8", errors="replace").read()
if not text.strip():
    print("FAIL: report empty"); sys.exit(1)
lines = text.splitlines()

def has_path(line, p):
    return re.search(r"(?<![\w./-])" + re.escape(p) + r"(?![\w./-])", line) is not None

# 1. every /etc/shells entry listed by absolute path
for p in EXPECTED:
    if not any(has_path(l, p) for l in lines):
        fail(f"shell path {p} from /etc/shells not listed")

# 2. no existing shell reported as missing / not executable
for p in EXPECTED:
    for l in lines:
        if has_path(l, p) and NEG.search(l):
            fail(f"report says existing shell {p} is missing/not executable: {l!r}")

# 3. existence/executability verification stated
low = text.lower()
if not (re.search(r"exist", low) and re.search(r"executable", low)):
    fail("no verification that shells exist as executable files")

# 4. current shell identified, and it names an actual shell
def shell_tokens(s):
    toks = re.findall(r"[A-Za-z0-9_./-]+", s)
    out = []
    for t in toks:
        b = t.rstrip(".").split("/")[-1].lstrip("-")
        if b in SHELL_NAMES:
            out.append(b)
    return out

found_label = False
named = False
for i, l in enumerate(lines):
    if re.search(r"current\s+shell|\$0", l, re.I):
        found_label = True
        after = re.split(r"current\s+shell|\$0", l, flags=re.I)[-1]
        cand = after
        if not shell_tokens(after):
            # value may be on the next non-empty, non-underline line
            for nl in lines[i + 1:i + 4]:
                if nl.strip() and not re.fullmatch(r"[\s=\-_*#]+", nl):
                    cand = nl
                    break
        if shell_tokens(cand):
            named = True
            break
if not found_label:
    fail("no 'current shell' / $0 entry in report")
elif not named:
    fail("current shell entry does not name a shell")

if failures:
    for f in failures:
        print("FAIL:", f)
    sys.exit(1)
print("PASS")
EOF
